                s = s.Replace("<E800 568><E563><E800 570><E164 3 87 1 2 7 0 0 1><E800 571><E149 3 4 4><E800 572><E139 3><E800 574><E041 3 2><E025 2>...is in fact Inspector Gregson himself?", "Eh bien, se pourrait-il que cet Hugh Boone...\r\n...soit en réalité l'inspecteur Gregson en personne ?");
                s = s.Replace("<E800 575><E041 1 0><E025 2><E333><E342>What?<E003 12>\r\nHow could that be?", "Quoi ?\r\nComment cela serait-il possible ?");
                s = s.Replace("<E800 576><E563><E800 578><E145 3 64><E800 579><E149 3 0 4><E800 580><E003 6><E800 582><E041 3 2><E025 2>Well if he was investigating on his own...", "S'il menait des investigations en solitaire...\r\n...il est fort probable que cette pièce lui servait\r\nde bureau secret.");
